#!/bin/bash

# 脚本说明：
# 校验 gozero 服务里由 goctl 生成的代码是否被人工改动过，供 ./mix lint gozero 调用
#
# 模板约定（gozero/template）：
#   1. 带 "// Code generated by goctl. DO NOT EDIT." 标记的文件不允许修改：
#      这里用仓库模板 + gozero/api/main.api + gozero/script/sql 重新生成到临时目录，再逐个比对内容
#   2. 带 "// Code scaffolded by goctl. Safe to edit." 标记的文件允许编写业务代码：
#      只校验标记注释本身没有被改写或删除，文件内容不做限制
#
# 用法：./checkGenerated.sh
# 退出码：0 校验通过（goctl 或 go 缺失时跳过并提示），1 存在被改动的生成产物
# 说明：
#   - 全部校验都在临时目录内进行，不会修改仓库中的任何文件
#   - goctl 生成路由分组与中间件的顺序存在小概率不确定性，比对失败时会重新生成再确认，
#     避免把工具自身的顺序抖动误判为人工改动

set -u

GREEN='\033[0;32m'
YELLOW='\033[1;33m'
RED='\033[0;31m'
NC='\033[0m'

print_info() {
	echo -e "${GREEN}[INFO]${NC} $1"
}

print_warn() {
	echo -e "${YELLOW}[WARN]${NC} $1"
}

print_error() {
	echo -e "${RED}[ERROR]${NC} $1"
}

if ! command -v goctl >/dev/null 2>&1 || ! command -v go >/dev/null 2>&1; then
	print_warn "未检测到 goctl 或 go，跳过 goctl 生成产物校验"
	exit 0
fi

script_dir=$(dirname "$(readlink -f "$0")")
gozero_root=$(cd "$script_dir/../.." && pwd)
repo_root=$(cd "$gozero_root/.." && pwd)
app_dir="$gozero_root/app"
api_file="$gozero_root/api/main.api"
template_home="$gozero_root/template"
sql_dir="$gozero_root/script/sql"
app_dir_relative="${app_dir#"$repo_root"/}"

do_not_edit_mark='// Code generated by goctl. DO NOT EDIT.'
safe_edit_mark='// Code scaffolded by goctl. Safe to edit.'

# 转成本机原生路径：goctl 是原生程序，Windows 下无法识别 /c/... 这类 POSIX 路径
native_path() {
	if command -v cygpath >/dev/null 2>&1; then
		cygpath -w "$1"
		return
	fi
	printf '%s' "$1"
}

# 比对前统一用 gofmt 归一化，只忽略格式化差异，业务改动仍然会体现出来
format_code() {
	if command -v gofmt >/dev/null 2>&1; then
		gofmt "$1"
		return
	fi
	cat "$1"
}

# 与 genOrm.sh 保持一致：表名转小驼峰作为 model 子目录
lower_camel() {
	local upper
	upper="$(awk -F'_' '{ for (i = 1; i <= NF; i++) printf "%s%s", toupper(substr($i, 1, 1)), substr($i, 2) }' <<<"$1")"
	printf "%s%s" "$(tr '[:upper:]' '[:lower:]' <<<"${upper:0:1}")" "${upper:1}"
}

extract_table_name() {
	sed -nE 's/^[[:space:]]*CREATE[[:space:]]+TABLE([[:space:]]+IF[[:space:]]+NOT[[:space:]]+EXISTS)?[[:space:]]+`?([A-Za-z0-9_]+)`?.*/\2/Ip' "$1" | head -n 1
}

# 判断仓库中是否存在文件名大小写完全一致的文件：
# Windows 文件系统大小写不敏感，goctl 生成的中间件骨架是小写文件名（usercontextMiddleware.go），
# 直接判断存在会把手写的驼峰文件（userContextMiddleware.go）误当成同一个文件
repo_file_exists() {
	local repo_file="$1"
	[ -f "$repo_file" ] || return 1
	ls -1 "$(dirname "$repo_file")" | grep -Fxq -- "$(basename "$repo_file")"
}

work_dir="$(mktemp -d)"
cleanup() {
	rm -rf "$work_dir"
}
trap cleanup EXIT

# 临时目录自身作为生成目标的模块根：goctl 要求 --dir 落在 go module 内，
# 复制 app 的 go.mod 可保证模块名与仓库一致，生成出的包路径也与仓库完全相同
mkdir -p "$work_dir/app"
cp "$app_dir/go.mod" "$work_dir/app/go.mod"
if [ -f "$app_dir/go.sum" ]; then
	cp "$app_dir/go.sum" "$work_dir/app/go.sum"
fi

# 取 go 认定的规范路径：goctl 内部用大小写敏感的前缀比较模块目录，
# Windows 下传入路径与磁盘真实大小写不一致时会直接报 no matched module
module_dir="$(cd "$work_dir/app" && go list -m -f '{{.Dir}}' 2>/dev/null)"
if [ -z "$module_dir" ]; then
	print_warn "无法解析临时模块路径，跳过 goctl 生成产物校验"
	exit 0
fi

if command -v cygpath >/dev/null 2>&1; then
	module_dir_posix="$(cygpath -u "$module_dir")"
else
	module_dir_posix="$module_dir"
fi

# 按仓库模板把 API 与 ORM 产物重新生成到临时模块
generate_all() {
	goctl api go -api "$(native_path "$api_file")" -dir "$module_dir" \
		--style=goZero --home "$(native_path "$template_home")" >>"$work_dir/gen.log" 2>&1 || return 1

	local sql_file table_name
	for sql_file in "$sql_dir"/*.sql; do
		[ -e "$sql_file" ] || continue
		table_name="$(extract_table_name "$sql_file")"
		[ -n "$table_name" ] || continue
		goctl model mysql ddl --style goZero --home "$(native_path "$template_home")" \
			--src "$(native_path "$sql_file")" \
			--dir "$module_dir/model/$(lower_camel "$table_name")" >>"$work_dir/gen.log" 2>&1 || return 1
	done

	return 0
}

# 比对不允许修改的生成文件，一致返回 0，存在差异时打印详情并返回 1
check_do_not_edit() {
	local local_failures=0 rel_path repo_file
	while IFS= read -r -d '' generated_file; do
		head -n 1 "$generated_file" | grep -qF "$do_not_edit_mark" || continue
		rel_path="${generated_file#"$module_dir_posix"/}"

		repo_file="$app_dir/$rel_path"
		if ! repo_file_exists "$repo_file"; then
			print_error "生成文件缺失：$rel_path（该文件由 goctl 生成，不允许删除）"
			local_failures=1
			continue
		fi

		if ! diff -q <(format_code "$generated_file") <(format_code "$repo_file") >/dev/null 2>&1; then
			print_error "生成文件被修改：$rel_path"
			echo "  下面 - 为仓库现状，+ 为按 gozero/template 重新生成的结果"
			diff -u <(format_code "$repo_file") <(format_code "$generated_file") | sed -n '1,40p'
			local_failures=1
		fi
	done < <(find "$module_dir_posix" -type f -name '*.go' -print0)

	return "$local_failures"
}

# 校验允许编辑文件的首行标记注释，被改写或删除时返回 1
check_safe_edit() {
	local local_failures=0 rel_path repo_file repo_mark
	while IFS= read -r -d '' generated_file; do
		head -n 1 "$generated_file" | grep -qF "$safe_edit_mark" || continue
		rel_path="${generated_file#"$module_dir_posix"/}"

		# 仓库里不存在的文件（例如已删除的 goctl 中间件骨架）不做要求
		repo_file="$app_dir/$rel_path"
		repo_file_exists "$repo_file" || continue

		repo_mark="$(head -n 1 "$repo_file" | tr -d '\r')"
		[ "$repo_mark" = "$safe_edit_mark" ] && continue

		# 手写实现可能与 goctl 生成文件同名（例如 recoveryMiddleware.go 与生成骨架路径完全一致），
		# 这类文件从来没有过标记，只有历史提交里出现过标记的文件才能说明标记被改写或删除了
		if ! git -C "$repo_root" log --format=%h -S"$safe_edit_mark" -- "$app_dir_relative/$rel_path" 2>/dev/null | head -n 1 | grep -q .; then
			print_info "跳过与生成文件同名且从未带标记的手写实现：$rel_path"
			continue
		fi

		print_error "可编辑文件的标记注释被改写或删除：$rel_path"
		echo "  期望首行：$safe_edit_mark"
		echo "  实际首行：$repo_mark"
		local_failures=1
	done < <(find "$module_dir_posix" -type f -name '*.go' -print0)

	return "$local_failures"
}

# 生成阶段切换到临时目录执行：goctl 在模块识别异常时会以调用者的当前目录为基准回退执行
# go mod init / go work use，若在仓库目录下执行会污染仓库根目录的 go.mod 与 go.work
cd "$work_dir" || exit 1

print_info "按仓库模板重新生成 goctl 产物（临时目录，不影响仓库文件）..."
if ! generate_all; then
	print_error "重新生成 goctl 产物失败，无法校验："
	cat "$work_dir/gen.log"
	exit 1
fi

print_info "校验不允许修改的生成文件（DO NOT EDIT）..."
# goctl 生成路由分组与中间件的顺序存在小概率不确定性，首次比对不一致时重新生成再确认
max_attempts=3
attempt=1
while true; do
	check_do_not_edit >"$work_dir/do_not_edit.log" 2>&1 && break
	if [ "$attempt" -ge "$max_attempts" ]; then
		break
	fi
	attempt=$((attempt + 1))
	print_info "本次生成结果与仓库存在差异，重新生成第 $attempt 次确认..."
	if ! generate_all; then
		print_error "重新生成 goctl 产物失败，无法校验："
		cat "$work_dir/gen.log"
		exit 1
	fi
done

failures=0
if [ -s "$work_dir/do_not_edit.log" ]; then
	cat "$work_dir/do_not_edit.log"
	failures=1
fi

print_info "校验允许编辑文件的首行标记注释（Safe to edit）..."
if ! check_safe_edit; then
	failures=1
fi

if [ "$failures" -ne 0 ]; then
	print_error "goctl 生成产物与 gozero/template 不一致，请执行 ./mix goctl-api 与 ./mix goctl-orm 重新生成"
	exit 1
fi

print_info "goctl 生成产物与 gozero/template 一致"
